297	/** Anything with zod's `safeParse`. */
298	interface Schema {
299	  safeParse(value: unknown): { success: boolean };
300	}
301	
302	/**
303	 * The private admission rules one kind of room applies (matches and duels share them): its matchmaking name, its
304	 * create and join option schemas, and its refusal messages.
305	 */
306	export interface AdmissionRules {
307	  readonly roomName: string;
308	  readonly createSchema: Schema;
309	  readonly joinSchema: Schema;
310	  readonly noSuchMessage: string;
311	  readonly codeRequiredMessage: string;
312	  readonly fullMessage: (maxClients: number) => string;
313	}
314	
315	/**
316	 * Checks a create or join request before matchmaking places it: Colyseus calls this for every `create`, `join`,
317	 * `joinOrCreate` and `joinById` before it reserves a seat. A request carries either a `createToken` (a create) or a
318	 * `code` (a join), never both and never neither. Refusals carry a readable message the client shows.
319	 */
320	export async function authorizePrivateEntry(options: unknown, rules: AdmissionRules): Promise<true> {
321	  const request = (options ?? {}) as { protocolVersion?: unknown; code?: unknown; createToken?: unknown };
322	  if (request.protocolVersion !== PROTOCOL_VERSION) {
323	    throw new ServerError(JoinRefusal.ProtocolMismatch, protocolMismatchMessage(request.protocolVersion));
324	  }
325	  const hasCode = request.code !== undefined;
326	  const hasToken = request.createToken !== undefined;
327	  if (hasCode === hasToken) throw new ServerError(JoinRefusal.BadRequest, MALFORMED_MATCH_REQUEST_MESSAGE);
328	  if (hasToken) {
329	    if (!rules.createSchema.safeParse(options).success) throw new ServerError(JoinRefusal.BadRequest, MALFORMED_MATCH_REQUEST_MESSAGE);
330	    return true;
331	  }
332	  if (!rules.joinSchema.safeParse(options).success) throw new ServerError(JoinRefusal.NoSuchMatch, rules.noSuchMessage);
333	  const [listing] = await matchMaker.query({ name: rules.roomName, code: request.code as string });
334	  if (listing === undefined) throw new ServerError(JoinRefusal.NoSuchMatch, rules.noSuchMessage);
335	  if (listing.locked || listing.clients >= listing.maxClients) {
336	    throw new ServerError(JoinRefusal.MatchFull, rules.fullMessage(listing.maxClients));
337	  }
338	  return true;
339	}
340	
341	/**
342	 * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
343	 * carrying the creator's token, then only seats carrying this room's code. Returns the creator's token still unspent
344	 * (undefined once the creator's seat is taken); throwing refuses and frees the seat.
345	 */
346	export function admitSeat(options: unknown, room: { readonly code: string; readonly createToken: string | undefined }, rules: AdmissionRules): string | undefined {
347	  const request = (options ?? {}) as { code?: unknown; createToken?: unknown };
348	  if (request.createToken === undefined) {
349	    if (request.code === room.code) return room.createToken;
350	    if (request.code !== undefined) throw new ServerError(JoinRefusal.NoSuchMatch, rules.noSuchMessage);
351	  } else if (request.code === undefined && room.createToken !== undefined && request.createToken === room.createToken) {
352	    return undefined;
353	  }
354	  throw new ServerError(JoinRefusal.CodeRequired, rules.codeRequiredMessage);
355	}

