252	/**
253	 * POST TEST_PLACEMENT_PATH with a TestPlacement body: 200 with the ship's new position, 400 for a malformed body, a
254	 * tile off the map or a tile a ship cannot sit on, 404 when no match or player matches.
255	 */
256	const placeShipEndpoint = createEndpoint(TEST_PLACEMENT_PATH, { method: "POST" }, async (context) => {
257	  const parsed = testPlacementSchema.safeParse(context.body);
258	  if (!parsed.success) return Response.json({ error: "malformed placement" }, { status: 400 });
259	  const { code, sessionId, tileX, tileY, heading } = parsed.data;
260	  const [listing] = await matchMaker.query({ name: MATCH_ROOM, code });
261	  const room = listing === undefined ? undefined : (matchMaker.getLocalRoomById(listing.roomId) as MatchRoom | undefined);
262	  if (room === undefined || room.clients.get(sessionId) === undefined) return Response.json({ error: "no such player" }, { status: 404 });
263	  try {
264	    room.placeShip(sessionId, { tileX, tileY, heading });
265	  } catch (error) {
