272	export async function startGameServer(options: GameServerOptions): Promise<RunningGameServer> {
273	  const server = defineServer({
274	    greet: false,
275	    gracefullyShutdown: options.handleSignals ?? true,
276	    transport: new WebSocketTransport({ maxPayload: MAX_FRAME_BYTES }),
277	    rooms: {
278	      // Private matches are found by their code. A create's one-time token is a filter field too, and no listing
279	      // holds it, so a request carrying one matches no existing match: `join` fails and `joinOrCreate` creates.
280	      [MATCH_ROOM]: defineRoom(MatchRoom).filterBy(["code", "createToken"]),
281	      // Standalone duels (the combat spike) are admitted the same way, under their own name.
282	      [DUEL_ROOM]: defineRoom(DuelRoom).filterBy(["code", "createToken"]),
283	    },
284	    ...(options.testPlacement === true ? { routes: createRouter({ placeShipEndpoint }) } : {}),
285	  });
286	  await server.listen(options.port, options.host);
287	  const address = server.transport.server?.address() as AddressInfo | null | undefined;
